template:
// Kahn's algorithm: returns a valid order, or empty if there is a cycle.
// prereq [a, b] means b must come before a  →  edge b → a.
vector<int> topoOrder(int n, const vector<vector<int>>& prereq) {
    vector<vector<int>> adj(n);
    vector<int> indeg(n, 0);
    for (auto& p : prereq) { adj[p[1]].push_back(p[0]); ++indeg[p[0]]; }

    queue<int> q;                                  // use priority_queue for lexicographically smallest
    for (int v = 0; v < n; ++v) if (indeg[v] == 0) q.push(v);   // ALL nodes, not just those in edges

    vector<int> out;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        out.push_back(u);
        for (int v : adj[u])
            if (--indeg[v] == 0) q.push(v);        // v's last prerequisite just finished
    }
    return (int)out.size() == n ? out : vector<int>{};   // short output ⇒ cycle
}

// Longest path in a DAG (min semesters / parallel courses): DP in topological order.
int minSemesters(int n, const vector<vector<int>>& prereq) {
    vector<int> order = topoOrder(n, prereq);
    if (order.empty()) return -1;
    vector<vector<int>> adj(n);
    for (auto& p : prereq) adj[p[1]].push_back(p[0]);
    vector<int> sem(n, 1);
    for (int u : order) for (int v : adj[u]) sem[v] = max(sem[v], sem[u] + 1);
    return *max_element(sem.begin(), sem.end());
}

// DFS colouring variant (cycle detection + order). 0 = white, 1 = grey (on stack), 2 = black.
bool dfs(int u, vector<vector<int>>& adj, vector<int>& color, vector<int>& out) {
    color[u] = 1;
    for (int v : adj[u]) {
        if (color[v] == 1) return false;           // grey → grey: back edge, cycle
        if (color[v] == 0 && !dfs(v, adj, color, out)) return false;
    }
    color[u] = 2; out.push_back(u);                // post-order; reverse `out` at the end
    return true;
}
